def min_weight_connectivity(n: int, edges: list[tuple[int, int, int]], queries: list[tuple[int, int, int]]) -> list[bool]:
    parent = list(range(n))
    rank = [0] * n
    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
    sorted_edges = sorted(edges, key=lambda e: e[2])
    indexed_q = sorted(enumerate(queries), key=lambda x: x[1][2])
    ans = [False] * len(queries)
    ei = 0
    for qi, (u, v, lim) in indexed_q:
        while ei < len(sorted_edges) and sorted_edges[ei][2] <= lim:
            union(sorted_edges[ei][0], sorted_edges[ei][1])
            ei += 1
        ans[qi] = (u == v) or (find(u) == find(v))
    return ans
