```typescript
function freeTimeSlots(schedules: Array<Array<[number, number]>>, boundStart: number, boundEnd: number): Array<[number, number]> {
  if (boundStart >= boundEnd) return [];
  const busy: Array<[number, number]> = [];
  for (const s of schedules) {
    for (const [a, b] of s) {
      const cl = Math.max(boundStart, a), cr = Math.min(boundEnd, b);
      if (cl < cr) busy.push([cl, cr]);
    }
  }
  busy.sort((x, y) => x[0] - y[0] || x[1] - y[1]);
  const res: Array<[number, number]> = [];
  let cur = boundStart;
  for (const [a, b] of busy) {
    if (a > cur) res.push([cur, a]);
    if (b > cur) cur = b;
  }
  if (cur < boundEnd) res.push([cur, boundEnd]);
  return res;
}
```

