```javascript
function courseOrder(n, prereqs) {
  const adj = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [c, p] of prereqs) {
    adj[p].push(c);
    indeg[c]++;
  }
  const avail = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) avail.push(i);
  const out = [];
  while (avail.length) {
    avail.sort((a, b) => a - b);
    const u = avail.shift();
    out.push(u);
    for (const v of adj[u]) {
      if (--indeg[v] === 0) avail.push(v);
    }
  }
  return out.length === n ? out : [];
}
```

