```cpp
std::vector<int> next_greater_circular(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> res(n, -1);
    std::stack<int> st;
    for (int i = 0; i < 2 * n; ++i) {
        int cur = nums[i % n];
        while (!st.empty() && nums[st.top()] < cur) {
            res[st.top()] = cur;
            st.pop();
        }
        if (i < n) st.push(i);
    }
    return res;
}
```

