std::vector<int> merge_k_sorted(const std::vector<std::vector<int>>& lists) {
    using T = std::tuple<int, int, int>;
    std::priority_queue<T, std::vector<T>, std::greater<T>> pq;
    size_t total = 0;
    for (int i = 0; i < static_cast<int>(lists.size()); ++i) {
        total += lists[i].size();
        if (!lists[i].empty()) pq.push({lists[i][0], i, 0});
    }
    std::vector<int> res;
    res.reserve(total);
    while (!pq.empty()) {
        auto [val, li, idx] = pq.top(); pq.pop();
        res.push_back(val);
        if (idx + 1 < static_cast<int>(lists[li].size())) {
            pq.push({lists[li][idx + 1], li, idx + 1});
        }
    }
    return res;
}
```

