    const st = [];
    let num = 0, op = '+';
    while (i < expr.length) {
      const c = expr[i++];
      if (c >= '0' && c <= '9') num = num * 10 + (c.charCodeAt(0) - 48);
      else if (c === '(') num = parseExpr();
      if (((c < '0' || c > '9') && c !== ' ') || i === expr.length || c === ')') {
        if (op === '+') st.push(num);
        else if (op === '-') st.push(-num);
        else if (op === '*') st.push(st.pop() * num);
        else if (op === '/') st.push(Math.trunc(st.pop() / num));
        op = c;
        num = 0;
        if (c === ')') break;
      }
    }
    return st.reduce((a, b) => a + b, 0);
