```typescript
class ExpiringMap<K, V> {
  private store = new Map<K, { val: V; exp: number }>();
  set(key: K, val: V, ttlMs: number, now: number): void {
    this.store.set(key, { val, exp: now + ttlMs });
  }
  get(key: K, now: number): V | undefined {
    const e = this.store.get(key);
    if (!e) return undefined;
    if (now >= e.exp) { this.store.delete(key); return undefined; }
    return e.val;
  }
  prune(now: number): number {
    let n = 0;
    for (const [k, e] of this.store) {
      if (now >= e.exp) { this.store.delete(k); n++; }
    }
    return n;
  }
}
```

