function kthSmallestMatrix(matrix: number[][], k: number): number {
  const n = matrix.length;
  let lo = matrix[0][0], hi = matrix[n - 1][n - 1];
  const countLE = (mid: number): number => {
    let cnt = 0, r = n - 1, c = 0;
    while (r >= 0 && c < n) {
      if (matrix[r][c] <= mid) { cnt += r + 1; c++; }
      else r--;
    }
    return cnt;
  };
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (countLE(mid) < k) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
```

