function leastInterval(tasks, cooldown) {
  if (!tasks.length) return 0;
  const freq = new Map();
  let maxF = 0;
  for (const t of tasks) {
    const c = (freq.get(t) || 0) + 1;
    freq.set(t, c);
    if (c > maxF) maxF = c;
  }
  let maxCount = 0;
  for (const c of freq.values()) if (c === maxF) maxCount++;
  return Math.max(tasks.length, (maxF - 1) * (cooldown + 1) + maxCount);
}
