function countInversions(nums: number[]): number {
  const arr = nums.slice();
  const tmp = new Array<number>(arr.length);
  function sort(l: number, r: number): number {
    if (r - l <= 1) return 0;
    const m = (l + r) >> 1;
    let inv = sort(l, m) + sort(m, r);
    let i = l, j = m, k = l;
    while (i < m && j < r) {
      if (arr[i] <= arr[j]) tmp[k++] = arr[i++];
      else { inv += m - i; tmp[k++] = arr[j++]; }
    }
    while (i < m) tmp[k++] = arr[i++];
    while (j < r) tmp[k++] = arr[j++];
    for (let p = l; p < r; p++) arr[p] = tmp[p];
    return inv;
  }
  return sort(0, arr.length);
}
```

