```cpp
std::string alien_order(const std::vector<std::string>& words) {
    std::unordered_map<char, std::unordered_set<char>> adj;
    std::unordered_map<char, int> indeg;
    for (const auto& w : words) for (char c : w) indeg.try_emplace(c, 0);
    for (size_t i = 0; i + 1 < words.size(); ++i) {
        const auto& a = words[i];
        const auto& b = words[i + 1];
        size_t len = std::min(a.size(), b.size());
        bool diff = false;
        for (size_t j = 0; j < len; ++j) {
            if (a[j] != b[j]) {
                if (adj[a[j]].insert(b[j]).second) indeg[b[j]]++;
                diff = true;
                break;
            }
        }
        if (!diff && a.size() > b.size()) return "";
    }
    std::queue<char> q;
    for (auto [c, d] : indeg) if (d == 0) q.push(c);
    std::string res;
    while (!q.empty()) {
        char u = q.front(); q.pop();
        res.push_back(u);
        for (char v : adj[u]) if (--indeg[v] == 0) q.push(v);
    }
    return res.size() == indeg.size() ? res : "";
}
