int min_eating_speed(const std::vector<int>& piles, int h) {
    int lo = 1, hi = *std::max_element(piles.begin(), piles.end());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long hrs = 0;
        for (int p : piles) hrs += (p + mid - 1) / mid;
        if (hrs <= h) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}
