from collections import deque

def shortest_grid_path(grid: list[list[int]]) -> int:
    if not grid or not grid[0] or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1
    R, C = len(grid), len(grid[0])
    if R == 1 and C == 1:
        return 0
    q = deque([(0, 0, 0)])
    seen = {(0, 0)}
    while q:
        r, c, d = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0 and (nr, nc) not in seen:
                if nr == R - 1 and nc == C - 1:
                    return d + 1
                seen.add((nr, nc))
                q.append((nr, nc, d + 1))
    return -1
