```javascript
function lfuCacheSim(capacity, ops) {
  const vals = new Map(), freqs = new Map(), buckets = new Map();
  let minF = 0;
  function touch(k) {
    const f = freqs.get(k);
    freqs.set(k, f + 1);
    const b = buckets.get(f);
    b.delete(k);
    if (b.size === 0 && f === minF) minF++;
    if (!buckets.has(f + 1)) buckets.set(f + 1, new Set());
    buckets.get(f + 1).add(k);
  }
  const out = [];
  for (const op of ops) {
    if (op[0] === 'get') {
      const k = op[1];
      if (capacity <= 0 || !vals.has(k)) { out.push(-1); continue; }
      touch(k);
      out.push(vals.get(k));
    } else {
      const [, k, v] = op;
      if (capacity <= 0) continue;
      if (vals.has(k)) { vals.set(k, v); touch(k); continue; }
      if (vals.size >= capacity) {
        const victim = buckets.get(minF).values().next().value;
        buckets.get(minF).delete(victim);
        vals.delete(victim); freqs.delete(victim);
      }
      vals.set(k, v); freqs.set(k, 1); minF = 1;
      if (!buckets.has(1)) buckets.set(1, new Set());
      buckets.get(1).add(k);
    }
  }
  return out;
}
