```cpp
int lcs_length(const std::string& a, const std::string& b) {
    if (a.size() < b.size()) return lcs_length(b, a);
    std::vector<int> dp(b.size() + 1, 0);
    for (char ca : a) {
        int prev = 0;
        for (size_t j = 1; j <= b.size(); ++j) {
            int tmp = dp[j];
            if (ca == b[j - 1]) dp[j] = prev + 1;
            else dp[j] = std::max(dp[j], dp[j - 1]);
            prev = tmp;
        }
    }
    return dp[b.size()];
}
```

