```cpp
#include <bit>
std::vector<int> rmq_batch(const std::vector<int>& a, const std::vector<std::pair<int,int>>& qs) {
    int n = static_cast<int>(a.size());
    int K = n > 0 ? std::bit_width(static_cast<unsigned>(n)) : 1;
    std::vector<std::vector<int>> st(K, std::vector<int>(n));
    if (n > 0) st[0] = a;
    for (int k = 1; k < K; ++k) {
        for (int i = 0; i + (1 << k) <= n; ++i) {
            st[k][i] = std::min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        }
    }
    std::vector<int> out;
    out.reserve(qs.size());
    for (auto [l, r] : qs) {
        int k = std::bit_width(static_cast<unsigned>(r - l + 1)) - 1;
        out.push_back(std::min(st[k][l], st[k][r - (1 << k) + 1]));
    }
    return out;
}
```

