from collections import deque, defaultdict

def word_ladder_length(begin: str, end: str, word_list: list[str]) -> int:
    if begin == end:
        return 1 if end in word_list else 0
    word_set = set(word_list)
    if end not in word_set:
        return 0
    patterns = defaultdict(list)
    for w in word_set:
        for i in range(len(w)):
            patterns[w[:i] + '*' + w[i+1:]].append(w)
    q = deque([(begin, 1)])
    seen = {begin}
    while q:
        w, d = q.popleft()
        for i in range(len(w)):
            pat = w[:i] + '*' + w[i+1:]
            for nxt in patterns[pat]:
                if nxt == end:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))
            patterns[pat].clear()
    return 0
```

