```javascript
function decodeString(s) {
  const counts = [], strs = [];
  let cur = '', k = 0;
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') {
      k = k * 10 + (ch.charCodeAt(0) - 48);
    } else if (ch === '[') {
      counts.push(k); strs.push(cur);
      k = 0; cur = '';
    } else if (ch === ']') {
      cur = strs.pop() + cur.repeat(counts.pop());
    } else {
      cur += ch;
    }
  }
  return cur;
}
