class WordIndex {
  private root: { next: Record<string, any>; end: boolean } = { next: {}, end: false };
  insert(word: string): void {
    let cur = this.root;
    for (const ch of word) {
      if (!cur.next[ch]) cur.next[ch] = { next: {}, end: false };
      cur = cur.next[ch];
    }
    cur.end = true;
  }
  private walk(s: string) {
    let cur = this.root;
    for (const ch of s) {
      if (!cur.next[ch]) return null;
      cur = cur.next[ch];
    }
    return cur;
  }
  hasWord(word: string): boolean {
    const n = this.walk(word);
    return Boolean(n && n.end);
  }
  startsWith(prefix: string): boolean {
    return this.walk(prefix) !== null;
  }
}
