std::string rle_encode(const std::string& s) {
    std::string out;
    for (size_t i = 0; i < s.size(); ) {
        size_t j = i;
        while (j < s.size() && s[j] == s[i]) ++j;
        out += std::to_string(j - i);
        out.push_back(s[i]);
        i = j;
    }
