def mst_weight(n: int, edges: list[tuple[int, int, int]]) -> int:
    if n <= 1:
        return 0
    p = list(range(n))
    def find(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    total, used = 0, 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            p[rv] = ru
            total += w
            used += 1
            if used == n - 1:
                return total
    return -1
