def max_tree_independent_set(n: int, values: list[int], edges: list[tuple[int, int]]) -> int:
    if n == 0:
        return 0
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)
    take = [0] * n
    skip = [0] * n
    for u in reversed(order):
        t = values[u]
        s = 0
        for v in adj[u]:
            if parent[v] == u:
                t += skip[v]
                s += max(take[v], skip[v])
        take[u] = max(0, t)
        skip[u] = s
    return max(take[0], skip[0])
```

