class TokenBucket:
    def __init__(self, rate: float, capacity: float, now: float = 0.0):
        self.rate = rate
        self.capacity = capacity
        self.tokens = capacity
        self.last_ts = now

    def consume(self, cost: float, now: float) -> bool:
        self.tokens += (now - self.last_ts) * self.rate
        self.last_ts = now
        if self.tokens >= cost:
            self.tokens -= cost
            return True
