function maxProfitK(k: number, prices: number[]): number {
  const n = prices.length;
  if (k <= 0 || n < 2) return 0;
  if (k >= Math.floor(n / 2)) {
    let prof = 0;
    for (let i = 1; i < n; i++) if (prices[i] > prices[i - 1]) prof += prices[i] - prices[i - 1];
    return prof;
  }
  const buy = new Array<number>(k + 1).fill(-Infinity);
  const sell = new Array<number>(k + 1).fill(0);
  for (const p of prices) {
    for (let t = 1; t <= k; t++) {
      buy[t] = Math.max(buy[t], sell[t - 1] - p);
      sell[t] = Math.max(sell[t], buy[t] + p);
    }
  }
  return sell[k];
}
