```cpp
int min_edit_distance(const std::string& a, const std::string& b) {
    if (a.size() < b.size()) return min_edit_distance(b, a);
    int m = static_cast<int>(a.size()), n = static_cast<int>(b.size());
    std::vector<int> prev(n + 1), cur(n + 1);
    std::iota(prev.begin(), prev.end(), 0);
    for (int i = 1; i <= m; ++i) {
        cur[0] = i;
        for (int j = 1; j <= n; ++j) {
            if (a[i - 1] == b[j - 1]) cur[j] = prev[j - 1];
            else cur[j] = 1 + std::min({prev[j], cur[j - 1], prev[j - 1]});
        }
        std::swap(prev, cur);
    }
    return prev[n];
}
