std::vector<long long> rect_sums(const std::vector<std::vector<int>>& mat, const std::vector<std::tuple<int,int,int,int>>& qs) {
    int R = static_cast<int>(mat.size());
    int C = R > 0 ? static_cast<int>(mat[0].size()) : 0;
    std::vector<std::vector<long long>> ps(R + 1, std::vector<long long>(C + 1, 0));
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c) {
            ps[r + 1][c + 1] = mat[r][c] + ps[r][c + 1] + ps[r + 1][c] - ps[r][c];
        }
    }
    std::vector<long long> out;
    out.reserve(qs.size());
    for (auto [r1, c1, r2, c2] : qs) {
        out.push_back(ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1] - ps[r2 + 1][c1] + ps[r1][c1]);
