def total_n_queens(n: int) -> int:
    mask = (1 << n) - 1
    def dfs(cols: int, d1: int, d2: int) -> int:
        if cols == mask:
            return 1
        ans = 0
        avail = mask & ~(cols | d1 | d2)
        while avail:
            bit = avail & -avail
            avail -= bit
            ans += dfs(cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1)
