class RetryQueue:
    def __init__(self, base_delay: int = 10, max_attempts: int = 3):
        self.base_delay = base_delay
        self.max_attempts = max_attempts
        self.tasks = {}
        self.dead_letter = []

    def enqueue(self, task_id: str, now: int = 0) -> None:
        self.tasks[task_id] = {'attempts': 0, 'ready_at': now}

    def pop_ready(self, now: int) -> str | None:
        ready = [k for k, v in self.tasks.items() if v['ready_at'] <= now]
        if not ready:
            return None
        ready.sort(key=lambda k: (self.tasks[k]['ready_at'], k))
        return ready[0]

    def fail(self, task_id: str, now: int) -> None:
        t = self.tasks[task_id]
        t['attempts'] += 1
        t['ready_at'] = now + self.base_delay * t['attempts']

