    res = [[0, 0]]
    heap = [(0, float('inf'))]
    for x, neg_h, r in events:
        while heap[0][1] <= x:
            heapq.heappop(heap)
        if neg_h:
            heapq.heappush(heap, (neg_h, r))
        cur = -heap[0][0]
        if res[-1][1] != cur:
            res.append([x, cur])
    return res[1:]
