function restoreIpAddresses(s) {
  const res = [];
  function valid(seg) {
    if (seg.length === 0 || seg.length > 3) return false;
    if (seg.length > 1 && seg[0] === '0') return false;
    return Number(seg) <= 255;
  }
  function dfs(idx, parts) {
    if (parts.length === 4) {
      if (idx === s.length) res.push(parts.join('.'));
      return;
    }
    for (let len = 1; len <= 3 && idx + len <= s.length; len++) {
      const seg = s.slice(idx, idx + len);
      if (valid(seg)) {
        parts.push(seg);
        dfs(idx + len, parts);
        parts.pop();
      }
    }
  }
  dfs(0, []);
  return res.sort();
}
