function robCircular(nums) {
  if (nums.length === 0) return 0;
  if (nums.length === 1) return nums[0];
  function linear(l, r) {
    let prev2 = 0, prev1 = 0;
    for (let i = l; i <= r; i++) {
      const cur = Math.max(prev1, prev2 + nums[i]);
      prev2 = prev1;
      prev1 = cur;
    }
    return prev1;
  }
  return Math.max(linear(0, nums.length - 2), linear(1, nums.length - 1));
}
```

