long long trap_rain(const std::vector<int>& h) {
    int l = 0, r = static_cast<int>(h.size()) - 1;
    int lmax = 0, rmax = 0;
    long long ans = 0;
    while (l < r) {
        if (h[l] < h[r]) {
            lmax = std::max(lmax, h[l]);
            ans += lmax - h[l];
            ++l;
        } else {
            rmax = std::max(rmax, h[r]);
            ans += rmax - h[r];
            --r;
        }
    }
    return ans;
}
