oracle_solution:
```cpp
int shortest_path_neg(int n, const std::vector<std::tuple<int,int,int>>& edges, int src, int dst) {
    const int INF = 1e9;
    std::vector<int> dist(n, INF);
    dist[src] = 0;
    for (int i = 0; i < n - 1; ++i) {
        for (auto [u, v, w] : edges) {
            if (dist[u] < INF && dist[u] + w < dist[v]) dist[v] = dist[u] + w;
