def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    trie = {}
    for w in words:
        cur = trie
        for ch in w:
            cur = cur.setdefault(ch, {})
        cur['$'] = w
    R, C = len(board), len(board[0])
    found = []
    def dfs(r: int, c: int, node: dict) -> None:
        ch = board[r][c]
        nxt = node.get(ch)
        if not nxt:
            return
        if '$' in nxt:
            found.append(nxt.pop('$'))
        board[r][c] = '#'
        if r > 0: dfs(r - 1, c, nxt)
        if r + 1 < R: dfs(r + 1, c, nxt)
        if c > 0: dfs(r, c - 1, nxt)
        if c + 1 < C: dfs(r, c + 1, nxt)
        board[r][c] = ch
        if not nxt:
            node.pop(ch)
    for r in range(R):
        for c in range(C):
            dfs(r, c, trie)
    return sorted(found)
```

