bool word_break(const std::string& s, const std::vector<std::string>& dict) {
    std::unordered_set<std::string> set(dict.begin(), dict.end());
    size_t n = s.size();
    std::vector<bool> dp(n + 1, false);
    dp[0] = true;
    for (size_t i = 1; i <= n; ++i) {
        for (size_t j = 0; j < i; ++j) {
