int longest_pal_subseq(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    std::vector<int> dp(n, 1), prev(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        std::vector<int> cur(n, 0);
        cur[i] = 1;
        for (int j = i + 1; j < n; ++j) {
            if (s[i] == s[j]) cur[j] = 2 + prev[j - 1];
            else cur[j] = std::max(prev[j], cur[j - 1]);
        }
        prev = std::move(cur);
    }
    return prev[n - 1];
}
```

