```typescript
function findAnagrams(s: string, p: string): number[] {
  if (s.length < p.length) return [];
  const cnt = new Int32Array(26);
  for (let i = 0; i < p.length; i++) {
    cnt[p.charCodeAt(i) - 97]++;
    cnt[s.charCodeAt(i) - 97]--;
  }
  let nonzero = 0;
  for (let i = 0; i < 26; i++) if (cnt[i] !== 0) nonzero++;
  const res: number[] = [];
  if (nonzero === 0) res.push(0);
  for (let i = p.length; i < s.length; i++) {
    const add = s.charCodeAt(i) - 97;
    const rem = s.charCodeAt(i - p.length) - 97;
    if (cnt[add] === 0) nonzero++;
    cnt[add]--;
    if (cnt[add] === 0) nonzero--;
    if (cnt[rem] === 0) nonzero++;
    cnt[rem]++;
    if (cnt[rem] === 0) nonzero--;
    if (nonzero === 0) res.push(i - p.length + 1);
  }
  return res;
}
```

