```cpp
std::vector<std::vector<int>> generate_spiral(int n) {
    if (n <= 0) return {};
    std::vector<std::vector<int>> m(n, std::vector<int>(n, 0));
    int top = 0, bot = n - 1, left = 0, right = n - 1, val = 1;
    while (top <= bot && left <= right) {
        for (int c = left; c <= right; ++c) m[top][c] = val++;
        top++;
        for (int r = top; r <= bot; ++r) m[r][right] = val++;
        right--;
        if (top <= bot) { for (int c = right; c >= left; --c) m[bot][c] = val++; bot--; }
        if (left <= right) { for (int r = bot; r >= top; --r) m[r][left] = val++; left++; }
    }
    return m;
}
```

