```cpp
int min_path_sum(const std::vector<std::vector<int>>& grid) {
    int R = static_cast<int>(grid.size()), C = static_cast<int>(grid[0].size());
    std::vector<int> dp(C, 0);
    dp[0] = grid[0][0];
    for (int c = 1; c < C; ++c) dp[c] = dp[c - 1] + grid[0][c];
    for (int r = 1; r < R; ++r) {
        dp[0] += grid[r][0];
        for (int c = 1; c < C; ++c) dp[c] = std::min(dp[c], dp[c - 1]) + grid[r][c];
    }
    return dp[C - 1];
}
