class Heap {
  private a: number[] = [];
  private cmp: (x: number, y: number) => number;
  constructor(cmp: (x: number, y: number) => number) { this.cmp = cmp; }
  get size(): number { return this.a.length; }
  peek(): number { return this.a[0]; }
  push(v: number): void {
    this.a.push(v);
    let i = this.a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.cmp(this.a[i], this.a[p]) < 0) { [this.a[i], this.a[p]] = [this.a[p], this.a[i]]; i = p; }
      else break;
    }
  }
  pop(): number {
    const top = this.a[0], last = this.a.pop()!;
    if (this.a.length) {
      this.a[0] = last;
      let i = 0, n = this.a.length;
      while (true) {
        let b = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < n && this.cmp(this.a[l], this.a[b]) < 0) b = l;
        if (r < n && this.cmp(this.a[r], this.a[b]) < 0) b = r;
        if (b === i) break;
        [this.a[i], this.a[b]] = [this.a[b], this.a[i]]; i = b;
      }
    }
    return top;
  }
}

function runningMedians(nums: number[]): number[] {
  const lo = new Heap((a, b) => b - a);
  const hi = new Heap((a, b) => a - b);
  const out: number[] = [];
  for (const x of nums) {
    lo.push(x);
    hi.push(lo.pop());
    if (hi.size > lo.size) lo.push(hi.pop());
    out.push(lo.size > hi.size ? lo.peek() : (lo.peek() + hi.peek()) / 2);
  }
  return out;
}
