long long largest_rect_area(const std::vector<int>& h) {
    std::vector<int> st;
    long long best = 0;
    int n = static_cast<int>(h.size());
    for (int i = 0; i <= n; ++i) {
        int cur = (i == n) ? 0 : h[i];
        while (!st.empty() && h[st.back()] > cur) {
            long long height = h[st.back()];
            st.pop_back();
            long long width = st.empty() ? i : i - st.back() - 1;
            best = std::max(best, height * width);
        }
        st.push_back(i);
    }
    return best;
}
