```python
def serialize_nary(root: dict | None) -> str:
    if root is None:
        return ''
    out = []
    def dfs(node: dict) -> None:
        out.append(str(node['val']))
        out.append(str(len(node['children'])))
        for ch in node['children']:
            dfs(ch)
    dfs(root)
    return ','.join(out)

def deserialize_nary(data: str) -> dict | None:
    if not data:
        return None
    it = iter(data.split(','))
    def build() -> dict:
        val = int(next(it))
        cnt = int(next(it))
        return {'val': val, 'children': [build() for _ in range(cnt)]}
    return build()
```

```python
def max_two_non_overlap(nums: list[int], first_len: int, second_len: int) -> int:
    n = len(nums)
    pref = [0] * (n + 1)
    for i, x in enumerate(nums):
        pref[i + 1] = pref[i] + x

    def solve(L: int, M: int) -> int:
        best_l = pref[L]
        ans = pref[L + M]
        for i in range(L + M, n + 1):
            best_l = max(best_l, pref[i - M] - pref[i - M - L])
            ans = max(ans, best_l + pref[i] - pref[i - M])
        return ans

    return max(solve(first_len, second_len), solve(second_len, first_len))
```

