  for (const a of asteroids) {
    let alive = true;
    while (alive && a < 0 && st.length > 0 && st[st.length - 1] > 0) {
      const top = st[st.length - 1];
      if (top < -a) st.pop();
      else if (top === -a) { st.pop(); alive = false; }
