```typescript
function longestPalindromicSubseq(s: string): number {
  const n = s.length;
  const dp = new Int32Array(n);
  for (let i = n - 1; i >= 0; i--) {
    dp[i] = 1;
    let prev = 0;
    for (let j = i + 1; j < n; j++) {
      const tmp = dp[j];
      if (s[i] === s[j]) {
        dp[j] = prev + 2;
      } else if (dp[j - 1] > dp[j]) {
        dp[j] = dp[j - 1];
      }
      prev = tmp;
    }
  }
  return n === 0 ? 0 : dp[n - 1];
}
```

