export function formatDurationMs(ms: number): string {
  if (ms === 0) return '0ms';
  const units: [string, number][] = [['h', 3600000], ['m', 60000], ['s', 1000], ['ms', 1]];
  let rem = ms;
  let out = '';
  for (const [u, size] of units) {
    const q = Math.floor(rem / size);
    if (q > 0) {
