#include <algorithm>
#include <utility>
#include <vector>

std::vector<std::pair<int, int>> k_closest_points(const std::vector<std::pair<int, int>>& pts, int k) {
    if (k <= 0) return {};
    std::vector<std::pair<int, int>> copy = pts;
    auto cmp = [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        long long da = 1LL * a.first * a.first + 1LL * a.second * a.second;
        long long db = 1LL * b.first * b.first + 1LL * b.second * b.second;
        if (da != db) return da < db;
        return a < b;
    };
    size_t kk = std::min(static_cast<size_t>(k), copy.size());
    std::nth_element(copy.begin(), copy.begin() + kk, copy.end(), cmp);
    copy.resize(kk);
    std::sort(copy.begin(), copy.end(), cmp);
    return copy;
}
```

