#include <numeric>
#include <vector>

bool can_partition_equal(const std::vector<int>& nums) {
    int total = std::accumulate(nums.begin(), nums.end(), 0);
    if (total % 2 != 0) return false;
    int target = total / 2;
    std::vector<char> dp(target + 1, 0);
    dp[0] = 1;
    for (int x : nums) {
        for (int s = target; s >= x; --s) {
            if (dp[s - x]) dp[s] = 1;
        }
    }
    return dp[target] != 0;
}
