std::vector<int> daily_temps_wait(const std::vector<int>& temps) {
    int n = static_cast<int>(temps.size());
    std::vector<int> ans(n, 0);
    std::vector<int> st;
    st.reserve(n);
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && temps[st.back()] < temps[i]) {
            int idx = st.back();
            st.pop_back();
            ans[idx] = i - idx;
        }
        st.push_back(i);
    }
    return ans;
}
