```typescript
function accountsMerge(accounts: string[][]): string[][] {
  const parent = new Map<string, string>();
  const owner = new Map<string, string>();
  const find = (x: string): string => {
    let r = x;
    while (parent.get(r) !== r) r = parent.get(r)!;
    let cur = x;
    while (cur !== r) {
      const nxt = parent.get(cur)!;
      parent.set(cur, r);
      cur = nxt;
    }
    return r;
  };
  for (const acc of accounts) {
    const name = acc[0];
    for (let i = 1; i < acc.length; i++) {
      const em = acc[i];
      if (!parent.has(em)) parent.set(em, em);
      owner.set(em, name);
      parent.set(find(em), find(acc[1]));
    }
  }
  const groups = new Map<string, string[]>();
  for (const em of parent.keys()) {
    const r = find(em);
    const list = groups.get(r) ?? [];
    list.push(em);
    groups.set(r, list);
  }
  const res: string[][] = [];
  for (const [r, list] of groups) {
    list.sort();
    res.push([owner.get(r)!, ...list]);
  }
  res.sort((a, b) => (a[0] !== b[0] ? (a[0] < b[0] ? -1 : 1) : (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0)));
  return res;
}
