#include <vector>

int find_number_of_lis(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> len(n, 1), cnt(n, 1);
    int best = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (nums[j] < nums[i]) {
                if (len[j] + 1 > len[i]) {
                    len[i] = len[j] + 1;
                    cnt[i] = cnt[j];
                } else if (len[j] + 1 == len[i]) {
                    cnt[i] += cnt[j];
                }
            }
        }
        best = std::max(best, len[i]);
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (len[i] == best) ans += cnt[i];
    }
    return ans;
}
